$appPage='dashboard';$appTitle='Account overview';require __DIR__.'/../includes/customer_header.php';$financial=new FinancialService($pdo);$account=$financial->accountForUser($customerId);$userStmt=$pdo->prepare('SELECT full_name,kyc_status FROM users WHERE user_id=?');$userStmt->execute([$customerId]);$customer=$userStmt->fetch();$recent=$pdo->prepare('SELECT * FROM financial_transactions WHERE user_id=? ORDER BY created_at DESC LIMIT 6');$recent->execute([$customerId]);$summary=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type IN ('card_funding','credit_disbursement') AND status='completed' THEN amount_cents ELSE 0 END),0) money_in,COALESCE(SUM(CASE WHEN type IN ('card_transfer','credit_repayment') AND status='completed' THEN amount_cents+fee_cents ELSE 0 END),0) money_out,COALESCE(SUM(CASE WHEN status='completed' THEN fee_cents ELSE 0 END),0) fees FROM financial_transactions WHERE user_id=? AND created_at>=DATE_FORMAT(UTC_DATE(),'%Y-%m-01')");$summary->execute([$customerId]);$totals=$summary->fetch();$cardCount=$pdo->prepare("SELECT COUNT(*) FROM linked_cards WHERE user_id=? AND status='active'");$cardCount->execute([$customerId]);$unread=$pdo->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL');$unread->execute([$customerId]);$credit=$pdo->prepare("SELECT COALESCE(SUM(outstanding_cents),0) FROM credit_facilities WHERE user_id=? AND status='active'");$credit->execute([$customerId]);
?><p>Welcome back, <?=e($customer['full_name'])?>.</p><div class="app-grid"><section class="panel span-4"><span class="muted">Available balance</span><div class="stat-value"><?=Money::format((int)$account['balance_cents'])?></div><small><?=e($account['account_number'])?> · USD</small></section><section class="panel span-4"><span class="muted">Active cards</span><div class="stat-value"><?=e($cardCount->fetchColumn())?></div><a href="card-center.php">Manage cards →</a></section><section class="panel span-4"><span class="muted">KYC status</span><div style="margin-top:10px"><span class="badge <?=e($customer['kyc_status'])?>"><?=e(str_replace('_',' ',$customer['kyc_status']))?></span></div></section><section class="panel span-4"><span class="muted">Money in this month</span><div class="stat-value"><?=Money::format((int)$totals['money_in'])?></div></section><section class="panel span-4"><span class="muted">Money out this month</span><div class="stat-value"><?=Money::format((int)$totals['money_out'])?></div></section><section class="panel span-4"><span class="muted">Fees this month</span><div class="stat-value"><?=Money::format((int)$totals['fees'])?></div></section><section class="panel span-8"><div style="display:flex;justify-content:space-between"><h2>Recent transactions</h2><a href="transactions.php">View all</a></div><?php $rows=$recent->fetchAll();if(!$rows):?><div class="empty">No Valtoria ledger transactions yet. Link a card or add a beneficiary to get started.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Reference</th><th>Type</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a href="transaction.php?reference=<?=urlencode($row['reference'])?>"><?=e($row['reference'])?></a></td><td><?=e(str_replace('_',' ',$row['type']))?></td><td class="money"><?=Money::format((int)$row['amount_cents'])?></td><td><span class="badge <?=e($row['status'])?>"><?=e($row['status'])?></span></td></tr><?php endforeach?></tbody></table></div><?php endif?></section><section class="panel span-4"><h2>Quick actions</h2><div class="actions"><a class="button button-primary" href="funding.php">Fund account</a><a class="button button-secondary" href="transfer.php">Send money</a><a class="button button-secondary" href="credit-center.php">Credit center</a></div><hr style="border:0;border-top:1px solid var(--valtoria-border);margin:22px 0"><p><strong><?=Money::format((int)$credit->fetchColumn())?></strong><br><span class="muted">Outstanding credit</span></p><p><strong><?=e($unread->fetchColumn())?></strong><br><span class="muted">Unread notifications</span></p></section></div><?php require __DIR__.'/../includes/customer_footer.php';?>
